public static class NotebookControlGuiTests {
 static int checks,layouts;
 static void Check(bool good,string label){checks++;if(!good)throw new Exception("case "+checks+": "+label);}
 static Dictionary<string,object> Map(params object[] pairs){var map=new Dictionary<string,object>();for(int i=0;i<pairs.Length;i+=2)map[(string)pairs[i]]=pairs[i+1];return map;}
 static NotebookGuiReply Reply(Dictionary<string,object> data){return new NotebookGuiReply{ok=true,data=data};}
 static Dictionary<string,object> State(string feature,int value,string unit,string semantics){return Map("feature",feature,"value",value,"unit",unit,"valueSemantics",semantics,"presenceConfirmed",true,"readbackConfirmed",true,"valueReadbackConfirmed",true,"writable",false);}
 static Dictionary<string,object> Identity(bool scan,string code="GU605MI"){
  string family=NotebookControlRules.Family(code);var result=Map("manufacturer","ASUSTeK COMPUTER INC.","model",code,"modelCode",code,"family",family,"chassisTypes",new[]{family=="handheld"?11:10},"identityReadConfirmed",true,"interfaceDriverConfirmed",true,"eligibleForStatus",true,"sourcePrepared",true,"driverQueryPerformed",!scan,"supportsWrite",false,"supportsFanCurve",false,"supportsPowerLimits",false,"supportsLedWrites",false,"hardwareReadValidated",false,"identityScope","osReportedManufacturerModelChassis","supportReason","SOURCE_PREPARED_READ_ONLY");
  var states=new List<object>();if(!scan){states.Add(State("cpuFan",2200,"rpm","fanSpeed"));states.Add(State("gpuFan",1500,"rpm","fanSpeed"));states.Add(State("cpuTemperature",55,"C","temperature"));states.Add(State("gpuTemperature",42,"C","temperature"));states.Add(State("chargerMode",1,"code","chargerType"));if(family!="handheld"){states.Add(State("middleFan",0,"rpm","fanSpeed"));states.Add(State("keyboardBrightness",2,"level","brightness"));}}result["states"]=states.ToArray();return result;
 }
 static Dictionary<string,object> Controls(string code="GU605MI"){
  var result=Identity(false,code);var rows=new List<object>();foreach(var spec in NotebookControlRules.Specs.Where(s=>!s.NotebookOnly||NotebookControlRules.Family(code)!="handheld"))rows.Add(Map("feature",spec.Name,"unit",spec.Unit,"endpointPresent",true,"writeSupported",true,"allowedValues",Enumerable.Range(spec.Minimum,spec.Maximum-spec.Minimum+1).ToArray(),"minimum",spec.Minimum,"maximum",spec.Maximum,"currentValue",spec.CanConfirm?(object)2:null,"valueReadbackConfirmed",spec.CanConfirm,"queryValue",spec.CanConfirm?2:0,"valueSemantics",spec.CanConfirm?"brightness":"nativeStatus","physicalValidation",false));
  result["supportsWrite"]=true;result["controlSchema"]=1;result["controlStates"]=rows.ToArray();result["setCapabilities"]=rows.Cast<Dictionary<string,object>>().Select(r=>(string)r["feature"]).ToArray();result["controlSessionToken"]=new string('a',32);result["controlReadToken"]=new string('b',32);result["controlIdentityToken"]=new string('c',64);return result;
 }
 static Dictionary<string,object> Row(Dictionary<string,object> data,string feature){return ((IEnumerable)data["controlStates"]).Cast<Dictionary<string,object>>().Single(r=>(string)r["feature"]==feature);}
 sealed class Fake:INotebookGuiControlBackend {
  public string Code="GU605MI";public object Session=new object();public int Reads,ControlReads,Sets,Disposals,Quarantines;public bool Locked;public Dictionary<string,object> CustomControls;public Func<Dictionary<string,object>,Task<NotebookGuiReply>> OnControl;public Func<Dictionary<string,object>,Dictionary<string,object>> CustomOutcome;public Action<Fake> BeforeEmit;public readonly List<Dictionary<string,object>> Requests=new List<Dictionary<string,object>>();
  public bool RestartRequired{get{return Locked;}}public object ControlSessionIdentity{get{return Session;}}
  public Task<NotebookGuiReply> Request(Dictionary<string,object> request){Reads++;Requests.Add(new Dictionary<string,object>(request));return Task.FromResult(Reply(Identity((string)request["op"]=="scan",Code)));}
  public Task<NotebookGuiReply> RequestControl(Dictionary<string,object> request,object expectedSession,Action beforeSend){Check(Object.ReferenceEquals(expectedSession,Session),"all fake controls bind the existing worker session");Requests.Add(new Dictionary<string,object>(request));if((string)request["op"]=="controlRead")ControlReads++;else{if(BeforeEmit!=null)BeforeEmit(this);Check(beforeSend!=null,"setting has an actual pre-frame callback");beforeSend();Sets++;}if(OnControl!=null)return OnControl(request);if((string)request["op"]=="controlRead")return Task.FromResult(Reply(CustomControls??Controls(Code)));return Task.FromResult(Reply(CustomOutcome==null?Outcome(request):CustomOutcome(request)));}
  public Dictionary<string,object> Outcome(Dictionary<string,object> request){string feature=(string)request["setting"];bool confirmed=feature=="keyboardBrightness";var data=Identity(false,Code);data["controlSchema"]=1;data["setting"]=feature;data["requestedValue"]=request["value"];data["writeAttempted"]=true;data["outputCompleted"]=true;data["driverAcknowledged"]=true;data["writeConfirmed"]=confirmed;data["restorable"]=false;data["requiresRestart"]=feature=="gpuMux";data["appliedState"]=confirmed?"confirmed":"submittedUnconfirmed";if(confirmed)data["readbackValue"]=request["value"];return data;}
  public void Quarantine(){Locked=true;Quarantines++;Session=null;}public void Dispose(){Disposals++;Session=null;}
 }
 static void Failure(Action action,string code){try{action();throw new Exception("expected "+code);}catch(Exception error){var wrapped=error as TargetInvocationException;var failure=(wrapped==null?error:wrapped.InnerException) as NotebookGuiFailure;if(failure==null)throw;Check(failure.Code==code,"fail-closed "+code);}}
 static NotebookGuiSnapshot Read(NotebookGuiReader reader){return reader.ReadAsync(CancellationToken.None).GetAwaiter().GetResult();}
 static void Set(object value,string name,object data){value.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).SetValue(value,data);}
 static object Get(object value,string name){return value.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(value);}
 static object Invoke(object value,string name,params object[] args){return value.GetType().GetMethod(name,BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance).Invoke(value,args);}
 static IEnumerable<T> Elements<T>(DependencyObject root)where T:DependencyObject{if(root is T)yield return (T)root;foreach(object child in LogicalTreeHelper.GetChildren(root)){var dep=child as DependencyObject;if(dep!=null)foreach(var item in Elements<T>(dep))yield return item;}}
 static void Pure(){
  var fake=new Fake();var reader=new NotebookGuiReader(fake);var snapshot=Read(reader);Check(fake.Reads==2&&fake.ControlReads==1&&fake.Sets==0&&snapshot.Controls.Options.Count==6,"manual scan/status/control capability request never applies a value");Check(snapshot.Controls.Options.Single(o=>o.Feature=="chargeLimit").CurrentValue==null&&snapshot.Controls.Options.Single(o=>o.Feature=="performanceMode").CurrentValue==null&&snapshot.Controls.Options.Single(o=>o.Feature=="keyboardBrightness").CurrentValue==2,"raw mode/charge queries are not current configuration");
  Failure(()=>reader.ApplyControlAsync(snapshot,"chargeLimit",80,false,false,false,CancellationToken.None).GetAwaiter().GetResult(),"CONTROL_DISABLED");Check(fake.Sets==0,"no control permission means no fake SET");var result=reader.ApplyControlAsync(snapshot,"chargeLimit",80,true,false,false,CancellationToken.None).GetAwaiter().GetResult();Check(!result.WriteConfirmed&&result.AppliedState=="submittedUnconfirmed"&&fake.Sets==1,"charge submission never fabricates readback confirmation");var submitted=fake.Requests.Last();Check(Object.Equals(submitted["experimental"],true)&&(string)submitted["sessionToken"]==new string('a',32)&&(string)submitted["identityToken"]==new string('c',64)&&!submitted.ContainsKey("endpoint")&&!submitted.ContainsKey("method"),"only typed single-setting fields cross the worker boundary");Failure(()=>reader.ApplyControlAsync(snapshot,"chargeLimit",80,true,false,false,CancellationToken.None).GetAwaiter().GetResult(),"STALE_CAPTURE");Check(fake.Sets==1,"capture is consumed once");
  foreach(string code in new[]{"RC71L","RC72LA","RC73YA","RC73XA","GA402RJ","GA403UI","GU605MI","GU605MZ","FX507ZC4","FA507NV"}){var model=new Fake{Code=code};var modelReader=new NotebookGuiReader(model);var observed=Read(modelReader);Check(observed.Controls.Options.Count==(code.StartsWith("RC")?2:6),"exact model retains its family capability scope "+code);}
  foreach(string reason in new[]{"expired","future","session"}){var current=new Fake();var live=new NotebookGuiReader(current);var data=Read(live);if(reason=="session")current.Session=new object();else typeof(NotebookGuiControlCapture).GetProperty("CapturedUtc").SetValue(data.Controls,DateTime.UtcNow.AddSeconds(reason=="expired"?-31:6),null);Failure(()=>live.ApplyControlAsync(data,"chargeLimit",80,true,false,false,CancellationToken.None).GetAwaiter().GetResult(),"STALE_CAPTURE");Check(current.Sets==0,"stale/future/session-invalid capture never submits "+reason);}
  foreach(string feature in new[]{"gpuEco","gpuMux"}){var gpu=new Fake();var live=new NotebookGuiReader(gpu);var data=Read(live);Failure(()=>live.ApplyControlAsync(data,feature,0,true,false,false,CancellationToken.None).GetAwaiter().GetResult(),"CONTROL_ACK_REQUIRED");Check(gpu.Sets==0,"GPU selection alone does not submit");if(feature=="gpuMux")Failure(()=>live.ApplyControlAsync(data,feature,0,true,true,false,CancellationToken.None).GetAwaiter().GetResult(),"CONTROL_ACK_REQUIRED");var applied=live.ApplyControlAsync(data,feature,0,true,true,true,CancellationToken.None).GetAwaiter().GetResult();Check(!applied.WriteConfirmed&&applied.NeedsRestart==(feature=="gpuMux"),"GPU result remains unconfirmed with explicit MUX restart fact");}
  var dark=new Fake();var darkReader=new NotebookGuiReader(dark);var darkSnapshot=Read(darkReader);Check(darkReader.ApplyControlAsync(darkSnapshot,"keyboardBrightness",0,true,false,false,CancellationToken.None).GetAwaiter().GetResult().WriteConfirmed,"real matching brightness readback can confirm a zero setting");
  foreach(object badValue in new object[]{null,"0",1}){var bad=new Fake();bad.CustomOutcome=request=>{var response=bad.Outcome(request);response["readbackValue"]=badValue;return response;};var live=new NotebookGuiReader(bad);var data=Read(live);Failure(()=>live.ApplyControlAsync(data,"keyboardBrightness",0,true,false,false,CancellationToken.None).GetAwaiter().GetResult(),"INVALID_RESPONSE");Check(bad.Sets==1,"missing/malformed/different readback never receives an invented brightness confirmation");}
  foreach(string malformed in new[]{"forged-native-value","setter-list","missing-presence","string-flag","duplicate-values","illegal-value","bad-token","wrong-identity","false-current","missing-row"}){var controls=Controls();var row=Row(controls,"chargeLimit");switch(malformed){case "forged-native-value":row["currentValue"]=80;row["valueReadbackConfirmed"]=true;break;case "setter-list":controls["setCapabilities"]=new string[0];break;case "missing-presence":row["endpointPresent"]=false;break;case "string-flag":row["writeSupported"]="true";break;case "duplicate-values":row["allowedValues"]=new[]{80,80};break;case "illegal-value":row["allowedValues"]=new[]{101};break;case "bad-token":controls["controlReadToken"]="cached";break;case "wrong-identity":controls["model"]="GA402RJ";break;case "false-current":row["currentValue"]=80;break;case "missing-row":controls["controlStates"]=((object[])controls["controlStates"]).Take(5).ToArray();break;}var bad=new Fake{CustomControls=controls};Failure(()=>Read(new NotebookGuiReader(bad)),"INVALID_RESPONSE");Check(bad.Sets==0,"malformed capability has no control side effect "+malformed);}
  foreach(string malformed in new[]{"false-confirmed","native-confirmed","restore-claim","wrong-model","missing-flag"}){var bad=new Fake();bad.CustomOutcome=request=>{var value=bad.Outcome(request);switch(malformed){case "false-confirmed":value["appliedState"]="confirmed";break;case "native-confirmed":value["writeConfirmed"]=true;value["appliedState"]="confirmed";break;case "restore-claim":value["restorable"]=true;break;case "wrong-model":value["modelCode"]="GA402RJ";break;case "missing-flag":value.Remove("writeAttempted");break;}return value;};var live=new NotebookGuiReader(bad);var data=Read(live);Failure(()=>live.ApplyControlAsync(data,"chargeLimit",80,true,false,false,CancellationToken.None).GetAwaiter().GetResult(),"INVALID_RESPONSE");Failure(()=>live.ApplyControlAsync(data,"chargeLimit",80,true,false,false,CancellationToken.None).GetAwaiter().GetResult(),"STALE_CAPTURE");Check(bad.Sets==1,"unknown response never retries or restores "+malformed);}
  var slow=new Fake();var slowReader=new NotebookGuiReader(slow,25);var slowData=Read(slowReader);var pending=new TaskCompletionSource<NotebookGuiReply>();slow.OnControl=request=>pending.Task;Failure(()=>slowReader.ApplyControlAsync(slowData,"chargeLimit",80,true,false,false,CancellationToken.None).GetAwaiter().GetResult(),"QUERY_TIMEOUT");Check(slowReader.RestartRequired&&slow.Quarantines==1&&slow.Sets==1,"outer set timeout locks backend without retry");Failure(()=>Read(slowReader),"RESTART_REQUIRED");Check(slow.Sets==1,"quarantined reader never respawns control connection");pending.SetResult(Reply(slow.Outcome(slow.Requests.Last())));
  foreach(string reason in new[]{"policy","session","capture","expiry","model","option","disposed"}){var queued=new Fake();var live=new NotebookGuiReader(queued);var data=Read(live);bool permission=true;queued.BeforeEmit=f=>{switch(reason){case "policy":permission=false;break;case "session":f.Session=new object();break;case "capture":typeof(NotebookGuiSnapshot).GetProperty("Controls").SetValue(data,null,null);break;case "expiry":typeof(NotebookGuiControlCapture).GetProperty("CapturedUtc").SetValue(data.Controls,DateTime.UtcNow.AddSeconds(-31),null);break;case "model":typeof(NotebookGuiSnapshot).GetProperty("ModelCode").SetValue(data,"GA402RJ",null);break;case "option":typeof(NotebookGuiControlOption).GetProperty("Supported").SetValue(data.Controls.Options.Single(o=>o.Feature=="chargeLimit"),false,null);break;case "disposed":live.Dispose();break;}};Failure(()=>live.ApplyControlAsync(data,"chargeLimit",80,true,false,false,CancellationToken.None,()=>{if(!permission)throw new NotebookGuiFailure("CONTROL_DISABLED",false);}).GetAwaiter().GetResult(),reason=="policy"?"CONTROL_DISABLED":"STALE_CAPTURE");Check(queued.Sets==0&&!queued.Locked,"queued invalidation emits no fake frame and does not kill or quarantine "+reason);}
  var cancel=new CancellationTokenSource();var cancelling=new Fake();var cancelReader=new NotebookGuiReader(cancelling);var cancelData=Read(cancelReader);cancelling.BeforeEmit=f=>cancel.Cancel();try{cancelReader.ApplyControlAsync(cancelData,"chargeLimit",80,true,false,false,cancel.Token).GetAwaiter().GetResult();throw new Exception("expected pre-frame cancellation");}catch(OperationCanceledException){Check(cancelling.Sets==0,"cancelled queued setting emits no frame");}cancel.Dispose();
  var backend=new NotebookWorkerGuiBackend();Failure(()=>backend.RequestControl(Map("op","set","experimental",true),new object(),()=>{}).GetAwaiter().GetResult(),"IDENTITY_CHANGED");Failure(()=>backend.RequestControl(Map("op","set","experimental",true),new object(),null).GetAwaiter().GetResult(),"CONTROL_DISABLED");var client=(WorkerClient)Get(backend,"client");Check(!client.Running,"unbound real backend cannot start process or native access");backend.Dispose();
 }
 static void Layout(MainWindow window,string name){foreach(double width in new[]{1180.0,1538.0}){window.Width=width;window.Height=860;Invoke(window,"ShowPage","笔记本与掌机");var root=(FrameworkElement)window.Content;root.Measure(new Size(width,826));root.Arrange(new Rect(0,0,width,826));root.UpdateLayout();layouts++;Check(!window.IsVisible&&PresentationSource.FromVisual(window)==null,"unshown layout stays native-free "+name);int measured=0;foreach(var text in Elements<TextBlock>((StackPanel)Get(window,"content"))){if(text.ActualWidth<1||text.ActualHeight<1||String.IsNullOrEmpty(text.Text))continue;measured++;Check(!Double.IsNaN(text.ActualWidth)&&!Double.IsInfinity(text.ActualWidth),"text remains finite "+name);if(text.TextWrapping==TextWrapping.NoWrap){var measure=new FormattedText(text.Text,System.Globalization.CultureInfo.CurrentUICulture,text.FlowDirection,new Typeface(text.FontFamily,text.FontStyle,text.FontWeight,text.FontStretch),text.FontSize,Brushes.White,1.0);Check(measure.WidthIncludingTrailingWhitespace<=text.ActualWidth+3,"control text does not overflow "+text.Text+" at "+width);}}Check(measured>=10,"layout measures actual page text instead of an unarranged window");}}
 static void FrameGates(MainWindow window,NotebookGuiSnapshot snapshot,Fake fake){
  var capture=snapshot.Controls;var policy=(HardwareControlPolicy)Get(window,"hardwareControlPolicy");var draft=(Dictionary<string,int>)Get(window,"notebookControlDraft");var previous=new Dictionary<string,int>(draft);string token=(string)Get(window,"notebookControlDraftToken");bool rendering=(bool)Get(window,"render");var captured=snapshot.CapturedUtc;var controlTime=capture.CapturedUtc;object session=fake.Session;int frames=fake.Sets;
  Action demand=()=>Invoke(window,"DemandNotebookControlSend",snapshot,capture,"chargeLimit",80);
  try{Set(window,"render",false);Set(window,"busy",true);Set(window,"notebookControlSubmitting",true);policy.SetEnabled(true);Set(window,"notebookControlDraftToken",capture.ReadToken);draft["chargeLimit"]=80;demand();Check(fake.Sets==frames,"own busy transaction permits its validated callback without emitting a frame itself");
   foreach(string field in new[]{"render","closing","notebookWaitingForRead"}){Set(window,field,true);Failure(demand,"CONTROL_DISABLED");Set(window,field,false);}Set(window,"busy",false);Failure(demand,"CONTROL_DISABLED");Set(window,"busy",true);Set(window,"notebookControlSubmitting",false);Failure(demand,"CONTROL_DISABLED");Set(window,"notebookControlSubmitting",true);policy.SetEnabled(false);Failure(demand,"CONTROL_DISABLED");policy.SetEnabled(true);
   Set(window,"notebookSnapshot",null);Failure(demand,"CONTROL_DISABLED");Set(window,"notebookSnapshot",snapshot);typeof(NotebookGuiSnapshot).GetProperty("Controls").SetValue(snapshot,null,null);Failure(demand,"CONTROL_DISABLED");typeof(NotebookGuiSnapshot).GetProperty("Controls").SetValue(snapshot,capture,null);
   typeof(NotebookGuiSnapshot).GetProperty("CapturedUtc").SetValue(snapshot,DateTime.UtcNow.AddSeconds(-31),null);Failure(demand,"CONTROL_DISABLED");typeof(NotebookGuiSnapshot).GetProperty("CapturedUtc").SetValue(snapshot,captured,null);typeof(NotebookGuiControlCapture).GetProperty("CapturedUtc").SetValue(capture,DateTime.UtcNow.AddSeconds(6),null);Failure(demand,"CONTROL_DISABLED");typeof(NotebookGuiControlCapture).GetProperty("CapturedUtc").SetValue(capture,controlTime,null);
   fake.Session=new object();Failure(demand,"CONTROL_DISABLED");fake.Session=session;draft["chargeLimit"]=81;Failure(demand,"CONTROL_DISABLED");draft["chargeLimit"]=80;Set(window,"notebookControlDraftToken",new string('d',32));Failure(demand,"CONTROL_DISABLED");Check(fake.Sets==frames&&!window.IsVisible,"actual MainWindow late guards are pure and cannot issue a command");
  }finally{Set(window,"render",rendering);Set(window,"busy",false);Set(window,"notebookControlSubmitting",false);policy.SetEnabled(false);Set(window,"notebookControlDraftToken",token);draft.Clear();foreach(var item in previous)draft.Add(item.Key,item.Value);Set(window,"notebookSnapshot",snapshot);typeof(NotebookGuiSnapshot).GetProperty("Controls").SetValue(snapshot,capture,null);typeof(NotebookGuiSnapshot).GetProperty("CapturedUtc").SetValue(snapshot,captured,null);typeof(NotebookGuiControlCapture).GetProperty("CapturedUtc").SetValue(capture,controlTime,null);fake.Session=session;}
 }
 [STAThread]public static int Main(){try{Pure();var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var window=new MainWindow(true);var fake=new Fake();var reader=new NotebookGuiReader(fake);var snapshot=Read(reader);Set(window,"notebookReader",reader);Invoke(window,"SetNotebookRead",snapshot);Layout(window,"controls");var box=(StackPanel)Get(window,"content");var texts=Elements<TextBlock>(box).Select(t=>t.Text).ToArray();Check(texts.Contains("设备设置")&&texts.Contains("充电上限")&&texts.Contains("运行模式")&&!texts.Contains("submittedUnconfirmed"),"controls use short visible captions, not raw protocol states");Check(Elements<ComboBox>(box).All(c=>!c.IsEnabled)&&Elements<Button>(box).Where(b=>Convert.ToString(b.Content)=="应用").All(b=>!b.IsEnabled),"render-only control widgets cannot edit or apply");int prior=fake.Sets;((Task)Invoke(window,"ApplyNotebookControl",snapshot,"chargeLimit",80)).GetAwaiter().GetResult();Check(fake.Sets==prior,"render-only callback cannot submit even with a prepared fake capture");
  var policy=(HardwareControlPolicy)Get(window,"hardwareControlPolicy");Set(window,"render",false);policy.SetEnabled(true);try{Check((bool)Invoke(window,"NotebookMayApplyControl",snapshot,"chargeLimit",80),"current snapshot with session-only permission admits explicit single-value apply");Check(!(bool)Invoke(window,"NotebookMayApplyControl",new object[]{null,"chargeLimit",80}),"missing snapshot cannot throw or grant permission");foreach(string blocked in new[]{"busy","closing","pageReadRunning","notebookWaitingForRead"}){Set(window,blocked,true);Check(!(bool)Invoke(window,"NotebookMayApplyControl",snapshot,"chargeLimit",80),"GUI guard blocks application "+blocked);Set(window,blocked,false);}policy.SetEnabled(false);Check(!(bool)Invoke(window,"NotebookMayApplyControl",snapshot,"chargeLimit",80),"GUI session permission cannot be recovered from a snapshot");policy.SetEnabled(true);Check(!(bool)Invoke(window,"NotebookMayApplyControl",Read(new NotebookGuiReader(new Fake())),"chargeLimit",80),"another snapshot reference cannot authorize current window");object session=fake.Session;fake.Session=new object();Check(!(bool)Invoke(window,"NotebookMayApplyControl",snapshot,"chargeLimit",80),"GUI detects lost worker session before callback");fake.Session=session;Check(!(bool)Invoke(window,"NotebookMayApplyControl",snapshot,"gpuEco",0),"GPU requires user display acknowledgement");Set(window,"notebookAcceptDisplay",true);Check(!(bool)Invoke(window,"NotebookMayApplyControl",snapshot,"gpuMux",0),"MUX requires separate restart acknowledgement");Set(window,"notebookAcceptReboot",true);Check((bool)Invoke(window,"NotebookMayApplyControl",snapshot,"gpuMux",0)&&fake.Sets==prior,"GPU acknowledgement changes only local permission, never sends a command");}finally{Set(window,"render",true);policy.SetEnabled(false);}
  FrameGates(window,snapshot,fake);
  var stamp=snapshot.CapturedUtc;Invoke(window,"SetNotebookControlObservation",snapshot,"keyboardBrightness",(object)null);Check(snapshot.Readings.Single(r=>r.Feature=="keyboardBrightness").Text=="—"&&!snapshot.Readings.Single(r=>r.Feature=="keyboardBrightness").Confirmed,"pending/unconfirmed change clears the preceding brightness value");Invoke(window,"SetNotebookControlObservation",snapshot,"keyboardBrightness",0);Check(snapshot.Readings.Single(r=>r.Feature=="keyboardBrightness").Text=="0 / 3"&&snapshot.Readings.Single(r=>r.Feature=="keyboardBrightness").Confirmed&&snapshot.CapturedUtc==stamp,"confirmed brightness zero updates only its observation without refreshing unrelated telemetry time");
  foreach(string code in new[]{"RC72LA","FA507NV"}){var model=new Fake{Code=code};var modelReader=new NotebookGuiReader(model);var modelData=Read(modelReader);Set(window,"notebookReader",modelReader);Invoke(window,"SetNotebookRead",modelData);Layout(window,code);var captions=Elements<TextBlock>((StackPanel)Get(window,"content")).Select(t=>t.Text).ToArray();Check(captions.Contains("显卡 MUX")==!code.StartsWith("RC"),"family-specific GUI does not invent handheld GPU hardware");}
  Set(window,"notebookReader",reader);Invoke(window,"SetNotebookRead",snapshot);typeof(NotebookGuiSnapshot).GetProperty("CapturedUtc").SetValue(snapshot,DateTime.UtcNow.AddSeconds(-31),null);Invoke(window,"NotebookStateExpiryTick",DateTime.UtcNow);Layout(window,"expired");Check(snapshot.Controls==null&&!Elements<TextBlock>((StackPanel)Get(window,"content")).Any(t=>t.Text=="设备设置"),"same-page expiry drops writable capture instead of retaining current controls");
  var task=new TaskCompletionSource<object>();Set(window,"notebookControlTask",task.Task);Check(window.NotebookReadBusy&&!window.NotebookCanPreviewReload&&Object.ReferenceEquals(window.NotebookReadTask,task.Task),"pending control participates in existing closing/reload lifecycle");Set(window,"notebookControlTask",null);((Task)Invoke(window,"DisposeNotebookStatusAsync")).GetAwaiter().GetResult();app.Shutdown();Console.WriteLine("Notebook control GUI: "+checks+" checks, "+layouts+" unshown layouts; native/WMI/ATKACPI/writes=0.");return 0;}catch(Exception error){Console.Error.WriteLine(error.InnerException??error);return 1;}}
